9→func ParseWireGuard(configText, customName string) (*ProxyResult, error) {
10→	conf := map[string]map[string]string{
11→		"interface": {},
12→		"peer":      {},
13→	}
14→	var section string
15→
16→	for _, line := range strings.Split(configText, "\n") {
17→		// Убираем комментарии
18→		if idx := strings.IndexAny(line, "#;"); idx != -1 {
19→			line = line[:idx]
20→		}
21→		line = strings.TrimSpace(line)
22→		if line == "" {
23→			continue
24→		}
25→
26→		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
27→			sName := strings.ToLower(line[1 : len(line)-1])
28→			if sName == "interface" || sName == "peer" {
29→				section = sName
30→			} else {
31→				section = ""
32→			}
33→			continue
34→		}
35→
36→		if section != "" && strings.Contains(line, "=") {
37→			parts := strings.SplitN(line, "=", 2)
38→			key := strings.TrimSpace(strings.ToLower(parts[0]))
39→			val := strings.TrimSpace(parts[1])
40→			conf[section][key] = val
41→		}
42→	}
43→
44→	iface := conf["interface"]
45→	peer := conf["peer"]
46→
47→	if len(iface) == 0 || len(peer) == 0 {
48→		return nil, &ParseError{Msg: "Invalid WireGuard config: missing Interface or Peer"}
49→	}
50→
51→	endpoint := peer["endpoint"]
52→	if endpoint == "" {
53→		return nil, &ParseError{Msg: "No Endpoint found"}
54→	}
55→
56→	var server, port string
57→	if strings.Contains(endpoint, "]:") {
58→		parts := strings.SplitN(endpoint, "]:", 2)
59→		server = parts[0][1:] // убираем [
60→		port = parts[1]
61→	} else if idx := strings.LastIndex(endpoint, ":"); idx != -1 {
62→		server = endpoint[:idx]
63→		port = endpoint[idx+1:]
64→	} else {
65→		return nil, &ParseError{Msg: "Invalid Endpoint format"}
66→	}
67→
68→	name := "WireGuard"
69→	if customName != "" {
70→		name = customName
71→	} else {
72→		lines := strings.Split(configText, "\n")
73→		for _, l := range lines {
74→			l = strings.TrimSpace(l)
75→			if strings.HasPrefix(l, "#") && len(l) > 2 {
76→				name = strings.TrimSpace(l[1:])
77→				break
78→			}
79→		}
80→		if name == "WireGuard" {
81→			name = "WG_" + server
82→		}
83→	}
84→
85→	addressRaw := iface["address"]
86→	if addressRaw == "" {
87→		return nil, &ParseError{Msg: "No Address found"}
88→	}
89→
90→	ips := strings.Split(addressRaw, ",")
91→	var ipV4, ipV6 string
92→	for _, ip := range ips {
93→		cleanIP := strings.TrimSpace(strings.Split(ip, "/")[0])
94→		if strings.Contains(cleanIP, ":") {
95→			if ipV6 == "" {
96→				ipV6 = cleanIP
97→			}
98→		} else {
99→			if ipV4 == "" {
100→				ipV4 = cleanIP
101→			}
102→		}
103→	}
104→
105→	if ipV4 == "" && ipV6 == "" {
106→		return nil, &ParseError{Msg: "No valid IP address found"}
107→	}
108→
109→	var y []string
110→	y = append(y, `- name: "`+name+`"`)
111→	y = append(y, "  type: wireguard")
112→	y = append(y, "  server: "+server)
113→	y = append(y, "  port: "+port)
114→
115→	if ipV4 != "" {
116→		y = append(y, "  ip: "+ipV4)
117→	}
118→	if ipV6 != "" {
