123→		y = append(y, "  private-key: "+pk)
124→	}
125→	if pubk := peer["publickey"]; pubk != "" {
126→		y = append(y, "  public-key: "+pubk)
127→	}
128→	if psk := peer["presharedkey"]; psk != "" {
129→		y = append(y, "  pre-shared-key: "+psk)
130→	}
131→
132→	if dnsRaw := iface["dns"]; dnsRaw != "" {
133→		var dnsList []string
134→		for _, d := range strings.Split(dnsRaw, ",") {
135→			dnsList = append(dnsList, strings.TrimSpace(d))
136→		}
137→		dnsJSON, _ := json.Marshal(dnsList)
