156→			if _, err := strconv.Atoi(v); err == nil {
157→				val, _ := strconv.Atoi(v)
158→				amnOpts[k] = val
159→			} else if strings.HasPrefix(v, "-") {
160→				if _, err := strconv.Atoi(v[1:]); err == nil {
161→					val, _ := strconv.Atoi(v)
162→					amnOpts[k] = val
163→				} else {
164→					amnOpts[k] = v
165→				}
166→			} else {
167→				amnOpts[k] = v
168→			}
169→		}
170→	}
171→
172→	if len(amnOpts) > 0 {
173→		y = append(y, "  amnezia-wg-option:")
174→		for k, v := range amnOpts {
175→			switch val := v.(type) {
176→			case string:
177→				if val == "" {
178→					y = append(y, "    "+k+`: ""`)
179→				} else {
180→					y = append(y, "    "+k+": "+val)
181→				}
182→			default:
183→				y = append(y, "    "+k+": "+strconv.Itoa(val.(int)))
184→			}
185→		}
186→	}
187→
188→	if allowed := peer["allowedips"]; allowed != "" {
189→		var alList []string
190→		for _, x := range strings.Split(allowed, ",") {
191→			alList = append(alList, strings.TrimSpace(x))
192→		}
193→		alJSON, _ := json.Marshal(alList)
194→		y = append(y, "  allowed-ips: "+string(alJSON))
195→	}
196→
197→	if ka := peer["persistentkeepalive"]; ka != "" {
198→		y = append(y, "  persistent-keepalive: "+ka)
199→	}
200→
201→	return &ProxyResult{
202→		YAML: strings.Join(y, "\n"),
203→		Name: name,
204→	}, nil
205→}
